"""Run one predetermined post-change qualification group with the exclusive Java slot."""
import argparse
import json
from pathlib import Path
import re
import subprocess
import sys

HERE = Path(__file__).resolve().parent
PHASE = HERE.parent
OLD = PHASE.parent / 'direct-memo-followup'
PACKAGE = 'org/eclipse/rdf4j/sail/lmdb/evaluation/'
FOCUSED = ('NativeResultMaterializerTest,LmdbNativeProjectionValueReuseTest,'
           'LmdbNativeIrFactorCoordinateTransportTest,LmdbNativeIrOptionalFanoutCoordinateTest,'
           'LmdbNativePackedFtreeTest#delayedPackedRowsFallBackAfterAdvanceAndIterationClose,'
           'KernelResultCoordinatesTest,KernelResultCoordinateRepresentationsTest,KernelResultRowSelectionsTest')
LIFETIME = 'LmdbNativeIrFactorCoordinateTransportTest#' + '+'.join((
    'compiledIrPreservesAliasedUnionAndNestedOptionalBags',
    'interpretedIrPreservesAliasedUnionAndNestedOptionalBags',
    'capturedFirstRowRemainsReadableAfterEarlyClose',
    'interpretedCapturedFirstRowRemainsReadableAfterEarlyClose',
    'compiledCapturedFirstRowRemainsReadableAfterCancellationAndClose',
    'interpretedCapturedFirstRowRemainsReadableAfterCancellationAndClose',
    'compiledCancellationRacingWithCloseReleasesTheLiveCoordinateLedger',
    'interpretedCancellationRacingWithCloseReleasesTheLiveCoordinateLedger'))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('stage', choices=('default', 'weak', 'strong-lifetime'))
    parser.add_argument('--runtime', type=Path, required=True)
    parser.add_argument('--attempt', required=True)
    parser.add_argument('--slot-granted', action='store_true')
    args = parser.parse_args()
    if not args.slot_granted:
        raise ValueError('Exclusive Java slot required')
    table = OLD / 'contracts/test-src' / (PACKAGE + 'NativeDirectValueMemoContractTest.java')
    integration = OLD / 'contracts/integration-src' / (PACKAGE + 'NativeDirectValueMemoIntegrationTest.java')
    retention = HERE / 'src' / (PACKAGE + 'NativeDirectValueMemoRetentionContractTest.java')
    source_args = []
    if args.stage == 'default':
        selection = FOCUSED + ',NativeDirectValueMemoContractTest,NativeDirectValueMemoIntegrationTest'
        enabled, policy, expected = 'false', 'strong', 138
        sources = [table, integration]
    elif args.stage == 'weak':
        methods = re.findall(r'\t@Test\n\tvoid (\w+)\(', table.read_text())
        if len(methods) != 20:
            raise ValueError('Historical table selection changed')
        methods.remove('strongOwnershipEndsWhenTheMemoCloses')
        selection = 'NativeDirectValueMemoContractTest#' + '+'.join(methods)
        selection += ',NativeDirectValueMemoIntegrationTest,NativeDirectValueMemoRetentionContractTest,' + LIFETIME
        enabled, policy, expected = 'true', 'weak', 47
        sources = [table, integration, retention]
    else:
        selection, enabled, policy, expected, sources = LIFETIME, 'true', 'strong', 8, []
    for source in sources:
        source_args += ['--source', str(source)]
    command = [sys.executable, str(HERE / 'run_contracts.py'), args.attempt,
        '--classpath', str(args.runtime / 'classpath.txt'), '--overlay', str(args.runtime / 'classes'),
        *source_args, '--selection', selection,
        '--property', 'rdf4j.lmdb.nativeValueMemo.enabled=' + enabled,
        '--property', 'rdf4j.lmdb.nativeValueMemo.retention=' + policy]
    if args.stage != 'default':
        command += ['--property', 'rdf4j.lmdb.resultCoordinateTransport=off']
    command += ['--slot-granted']
    completed = subprocess.run(command, check=False)
    if completed.returncode:
        sys.exit(completed.returncode)
    receipt = json.loads((HERE / 'validation' / args.attempt / 'receipt.json').read_text())
    if not receipt['passed'] or receipt['results'] != dict(tests=expected, failures=0, errors=0, skipped=0):
        raise ValueError('Qualification case count or outcome differs from the predetermined group')
    print(json.dumps({'group': args.stage, 'passingTests': expected, 'attempt': args.attempt}))


if __name__ == '__main__':
    main()
